/**
 * Message and payload don't define equals, so have to rely on another way to define equality; serialized bytes!
 * The assumption is that serialize(deserialize(serialize(message))) == serialize(message)
 */
@Test
public void testMessageSerialization() throws Exception {
    SchemaProvider schema = Mockito.mock(SchemaProvider.class, Mockito.CALLS_REAL_METHODS);
    ReadCommand.Serializer readCommandSerializer = new ReadCommand.Serializer(schema);
    Supplier<? extends IVersionedAsymmetricSerializer<?, ?>> original = Verb.READ_REQ.unsafeSetSerializer(() -> readCommandSerializer);
    try (DataOutputBuffer first = new DataOutputBuffer(1024);
        DataOutputBuffer second = new DataOutputBuffer(1024)) {
        qt().withShrinkCycles(0).forAll(MESSAGE_GEN).checkAssert(orFail(message -> {
            withTable(schema, message, orFail(ignore -> {
                for (MessagingService.Version version : MessagingService.Version.supportedVersions()) {
                    first.clear();
                    second.clear();
                    // sync the clock with the generated createdAtNanos
                    FixedMonotonicClock.setNowInNanos(message.createdAtNanos());
                    serializer.serialize(message, first, version.value);
                    Message<Object> read = serializer.deserialize(new DataInputBuffer(first.buffer(), true), FBUtilities.getBroadcastAddressAndPort(), version.value);
                    serializer.serialize(read, second, version.value);
                    // using hex as byte buffer equality kept failing, and was harder to debug difference
                    // using hex means the specific section of the string that is different will be shown
                    Assertions.assertThat(ByteBufferUtil.bytesToHex(second.buffer())).as("Property serialize(deserialize(serialize(message))) == serialize(message) " + "was violated for version %s and verb %s" + "\n first=%s" + "\nsecond=%s\n", version, message.header.verb, // toString methods are not relyable for messages, so use reflection to generate one
                    new Object() {

                        public String toString() {
                            return CassandraGenerators.toStringRecursive(message);
                        }
                    }, new Object() {

                        public String toString() {
                            return CassandraGenerators.toStringRecursive(read);
                        }
                    }).isEqualTo(ByteBufferUtil.bytesToHex(first.buffer()));
                }
            }));
        }));
    } finally {
        Verb.READ_REQ.unsafeSetSerializer(original);
    }
}

@Test
public void pushSchemaMutationsOnlyToViableNodes() throws UnknownHostException {
    Wrapper wrapper = new Wrapper();
    Collection<Mutation> mutations = Arrays.asList(mock(Mutation.class));
    EndpointState validState = mock(EndpointState.class);
    InetAddressAndPort thisNode = wrapper.configureMocksForEndpoint(FBUtilities.getBroadcastAddressAndPort(), validState, MessagingService.current_version, false);
    InetAddressAndPort unkonwnNode = wrapper.configureMocksForEndpoint("10.0.0.1:8000", validState, null, false);
    InetAddressAndPort invalidMessagingVersionNode = wrapper.configureMocksForEndpoint("10.0.0.2:8000", validState, MessagingService.VERSION_30, false);
    InetAddressAndPort regularNode = wrapper.configureMocksForEndpoint("10.0.0.3:8000", validState, MessagingService.current_version, false);
    when(wrapper.gossiper.getLiveMembers()).thenReturn(Sets.newHashSet(thisNode, unkonwnNode, invalidMessagingVersionNode, regularNode));
    ArgumentCaptor<Message> msg = ArgumentCaptor.forClass(Message.class);
    ArgumentCaptor<InetAddressAndPort> targetEndpoint = ArgumentCaptor.forClass(InetAddressAndPort.class);
    doNothing().when(wrapper.messagingService).send(msg.capture(), targetEndpoint.capture());
    Pair<Set<InetAddressAndPort>, Set<InetAddressAndPort>> result = wrapper.coordinator.pushSchemaMutations(mutations);
    assertThat(result.left()).containsExactlyInAnyOrder(regularNode);
    assertThat(result.right()).containsExactlyInAnyOrder(thisNode, unkonwnNode, invalidMessagingVersionNode);
    assertThat(msg.getAllValues()).hasSize(1);
    assertThat(msg.getValue().payload).isEqualTo(mutations);
    assertThat(msg.getValue().verb()).isEqualTo(Verb.SCHEMA_PUSH_REQ);
    assertThat(targetEndpoint.getValue()).isEqualTo(regularNode);
}

@Test
public void reset() throws UnknownHostException {
    Collection<Mutation> mutations = Arrays.asList(mock(Mutation.class));
    Wrapper wrapper = new Wrapper();
