    boolean valuesStarted = false;
    int count = 0;
    int nullcount = 0;
    for (String line : lines) {
        if (line.startsWith("Values:")) {
            valuesStarted = true;
            continue;
        }
        if (valuesStarted) {
            if ("-----".equals(line)) {
                continue;
            }
            if (null == values.get(count++)) {
                nullcount++;
                Assert.assertEquals("null", line);
            }
        }
    }
    Assert.assertEquals(values.stream().filter(Objects::isNull).count(), nullcount);
}

